  data[offset + 1] = Math.round((color[1] * sourceAlpha + data[offset + 1] * destFactor) / outAlpha);
  data[offset + 2] = Math.round((color[2] * sourceAlpha + data[offset + 2] * destFactor) / outAlpha);
