  if (alpha <= 0) return 0;

  if (isAllowed && !isAllowed(sx, sy)) return 0;

  const startOffset = (sy * w + sx) * 4;
  const target = [data[startOffset], data[startOffset + 1], data[startOffset + 2], data[startOffset + 3]];
